// A Google-Maps-style vector map: light-blue ocean, a faint lat/long graticule,
// warm-grey landmasses with a soft drop shadow for depth, and a subtle host-nation
// tint. Tile-free on purpose so it still renders inside the Discord activity iframe
// (external map tiles are blocked there — see the header note). It reads as a light
// map panel even on a dark UI, like an embedded Google Map.
export function NorthAmericaMap() {
  return (
    <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full" aria-hidden="true">
      <defs>
        <linearGradient id="na-ocean" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#cfe6fb" />
          <stop offset="100%" stopColor="#a9d2f0" />
        </linearGradient>
        <filter id="na-land-shadow" x="-5%" y="-5%" width="110%" height="115%">
          <feDropShadow dx="0" dy="0.5" stdDeviation="0.6" floodColor="#1d3b53" floodOpacity="0.22" />
        </filter>
      </defs>

      {/* Ocean */}
      <rect x="0" y="0" width="100" height="100" fill="url(#na-ocean)" />

      {/* Graticule — faint grid lines, like a real map */}
      <g stroke="#ffffff" strokeOpacity="0.3" strokeWidth="0.12">
        {[12.5, 25, 37.5, 50, 62.5, 75, 87.5].map((x) => <line key={`v${x}`} x1={x} y1="0" x2={x} y2="100" />)}
        {[12.5, 25, 37.5, 50, 62.5, 75, 87.5].map((y) => <line key={`h${y}`} x1="0" y1={y} x2="100" y2={y} />)}
      </g>

      {/* Landmasses — warm map greys with a soft raised shadow */}
      <g filter="url(#na-land-shadow)">
        <path d={NA_PATHS.CA} fill="#eceee9" stroke="#c7cdc4" strokeWidth="0.18" strokeLinejoin="round" />
        <path d={NA_PATHS.US} fill="#eef1ea" stroke="#c7cdc4" strokeWidth="0.18" strokeLinejoin="round" />
        <path d={NA_PATHS.MX} fill="#f1ece2" stroke="#c7cdc4" strokeWidth="0.18" strokeLinejoin="round" />
      </g>

      {/* Subtle host-nation tint to anchor the World Cup framing */}
      <path d={NA_PATHS.US} fill="#34d399" fillOpacity="0.14" />
      <path d={NA_PATHS.MX} fill="#f59e0b" fillOpacity="0.16" />
      <path d={NA_PATHS.CA} fill="#ef4444" fillOpacity="0.10" />
    </svg>
  );
}
